class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def swapPairs(self, head):
        values = []
        cur = head
        while cur:
            values.append(cur.val)
            cur = cur.next
        for i in range(0, len(values) - 1, 2):
            values[i], values[i + 1] = values[i + 1], values[i]

        cur = head
        for value in values:
            cur.val = value
            cur = cur.next
        return head

